Я новичок на форуме и еще только изучаю эту систему.Это код часов, который я вставил в свой старый трекер Xbtit.Вы можете сами модифицировать его и поставить куда хотите.<br />
<br />
Демо: -----<br />
<br />
<br />
<code class="xfBb-icode">
&lt;html&gt;
&lt;head&gt;
&lt;style&gt;
.clockStyle {
    background-color:#FFFFFF;
    border-bottom-right-radius:1em;
    padding:6px;
    color:#000000;
    font-family:&quot;Arial Black&quot;, Gadget, sans-serif;
    font-size:12px;
    font-weight:bold;
    letter-spacing: 2px;
    display:inline;
}
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;td align=&quot;right&quot;&gt;&lt;font size=&quot;3&quot;&gt;&lt;b&gt;&lt;?php echo &quot;&quot;.$language[&quot;MNU_TIME&quot;].&quot;&quot;?&gt;&lt;/b&gt;&amp;nbsp;&amp;nbsp;&lt;div id=&quot;clockDisplay&quot; class=&quot;clockStyle&quot;&gt;&lt;/div&gt;&lt;/td&gt;
&lt;script&gt;
function renderTime() {
    var currentTime = new Date();
    var diem = &quot;AM&quot;;
    var h = currentTime.getHours();
    var m = currentTime.getMinutes();
    var s = currentTime.getSeconds();
    setTimeout(&#039;renderTime()&#039;,1000);
    if (h == 0) {
        h = 12;
    } else if (h &gt; 12) {
        h = h - 12;
        diem=&quot;PM&quot;;
    }
    if (h &lt; 10) {
        h = &quot;0&quot; + h;
    }
    if (m &lt; 10) {
        m = &quot;0&quot; + m;
    }
    if (s &lt; 10) {
        s = &quot;0&quot; + s;
    }
    var myClock = document.getElementById(&#039;clockDisplay&#039;);
    myClock.textContent = h + &quot;:&quot; + m + &quot;:&quot; + s + &quot; &quot; + diem;
    myClock.innerText = h + &quot;:&quot; + m + &quot;:&quot; + s + &quot; &quot; + diem;
}
renderTime();
&lt;/script&gt;
&lt;/body&gt;
&lt;/html
</code>
